-- Village panchayat master data for Kallakurichi, Tiruvannamalai, Viluppuram
-- Source: Tamil Nadu Rural Development & Panchayat Raj LGD list
--   https://www.tnrd.tn.gov.in/databases.html
--
-- Official village panchayat counts:
--   Kallakurichi     412
--   Tiruvannamalai   860
--   Viluppuram       688
-- Extra JSON keeps LGD village code and block for review.
-- Districts are created if missing. Safe to re-run (skips existing codes).
-- Requires organization.id = 1 (change @org_id if needed).
--
--   mysql -u root -p skac_new < deploy/mysql/master_villages.sql

USE skac_new;
SET NAMES utf8mb4;
SET @org_id := 1;

-- Districts (codes match app.services.config_defaults.TN_DISTRICTS slugs)
INSERT INTO config_item (organization_id, kind, parent_id, code, name, is_active, sort_order)
SELECT @org_id, 'district', NULL, 'kallakurichi', 'Kallakurichi', 1, 8
WHERE NOT EXISTS (
  SELECT 1 FROM config_item c
  WHERE c.organization_id = @org_id AND c.kind = 'district' AND c.code = 'kallakurichi' AND c.is_deleted = 0
);

INSERT INTO config_item (organization_id, kind, parent_id, code, name, is_active, sort_order)
SELECT @org_id, 'district', NULL, 'tiruvannamalai', 'Tiruvannamalai', 1, 33
WHERE NOT EXISTS (
  SELECT 1 FROM config_item c
  WHERE c.organization_id = @org_id AND c.kind = 'district' AND c.code = 'tiruvannamalai' AND c.is_deleted = 0
);

INSERT INTO config_item (organization_id, kind, parent_id, code, name, is_active, sort_order)
SELECT @org_id, 'district', NULL, 'viluppuram', 'Viluppuram', 1, 36
WHERE NOT EXISTS (
  SELECT 1 FROM config_item c
  WHERE c.organization_id = @org_id AND c.kind = 'district' AND c.code = 'viluppuram' AND c.is_deleted = 0
);

SET @d_kallakurichi := (SELECT id FROM config_item WHERE organization_id=@org_id AND kind='district' AND code='kallakurichi' AND is_deleted=0 ORDER BY id LIMIT 1);
SET @d_tiruvannamalai := (SELECT id FROM config_item WHERE organization_id=@org_id AND kind='district' AND code='tiruvannamalai' AND is_deleted=0 ORDER BY id LIMIT 1);
SET @d_viluppuram := (SELECT id FROM config_item WHERE organization_id=@org_id AND kind='district' AND code='viluppuram' AND is_deleted=0 ORDER BY id LIMIT 1);

SELECT
  CASE WHEN @d_kallakurichi IS NULL OR @d_tiruvannamalai IS NULL OR @d_viluppuram IS NULL
       THEN 'ERROR: district rows were not found — check organization_id / district seed'
       ELSE CONCAT(
         'Districts OK  kallakurichi=', @d_kallakurichi,
         ' tiruvannamalai=', @d_tiruvannamalai,
         ' viluppuram=', @d_viluppuram)
  END AS district_check;

-- Kallakurichi village panchayats (412)

