  UNION ALL SELECT @org_id AS organization_id, 'village' AS kind, @d_kallakurichi AS parent_id, 'a-kurumbur' AS code, 'A.Kurumbur' AS name, '{"lgd_village_code":"233751","block":"Tirunavalur"}' AS extra, 1 AS is_active, 1 AS sort_order
