) v
WHERE v.parent_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM config_item c
    WHERE c.organization_id = v.organization_id
      AND c.kind = 'village'
      AND c.parent_id = v.parent_id
      AND c.code = v.code
      AND c.is_deleted = 0
  );

